<script lang="ts">
 import {onMount} from 'svelte';import {api,labels,type Entry,type Kind} from './api';import EntryEditor from './EntryEditor.svelte';
 export let kind:Kind;let items:Entry[]=[],error='',loading=true,editing=false,selected:Entry|null=null,trash=false,page=1,totalPages=1;
 async function load(){loading=true;error='';try{const result=await api<{items:Entry[];meta:{totalPages:number}}>(`/content/manage/${kind}?page=${page}&trash=${trash}`);items=result.items;totalPages=result.meta.totalPages;}catch(e){error=String(e);}finally{loading=false;}}
 onMount(load);
 async function action(entry:Entry,type:'unpublish'|'restore'|'delete'){if(type==='delete'&&!confirm('移入回收站并下架？内容可以恢复。'))return;try{await api(`/content/manage/${kind}/${entry.id}${type==='delete'?'':'/'+type}`,type==='delete'?'DELETE':'POST',{version:entry.version});await load();}catch(e){error=String(e);}}
</script>
{#if editing}<EntryEditor {kind} entry={selected} onclose={()=>{editing=false;void load();}} onsaved={()=>void load()}/>{:else}
<section class="panel"><div class="section-head"><div><p class="eyebrow">CONTENT</p><h2>{labels[kind]}管理</h2><p class="muted">管理内容、编辑稿和公开版本。</p></div><button class="primary" onclick={()=>{selected=null;editing=true;}}>＋ 新建{labels[kind]}</button></div>
<div class="toolbar"><button class:active={!trash} onclick={()=>{trash=false;page=1;void load();}}>全部内容</button><button class:active={trash} onclick={()=>{trash=true;page=1;void load();}}>回收站</button><button onclick={load}>刷新</button></div>
{#if error}<p role="alert" class="error">{error}</p>{/if}
{#if loading}<p class="empty">正在读取…</p>{:else if !items.length}<div class="empty"><h3>{trash?'回收站为空':'还没有内容'}</h3><p>从这里开始记录你的故事。</p></div>{:else}<div class="table-wrap"><table><thead><tr><th>标题</th><th>状态</th><th>最近更新</th><th>操作</th></tr></thead><tbody>{#each items as item}<tr><td><strong>{item.data.title}</strong><small>{item.slug}</small></td><td><span class="badge">{item.status==='TRASH'?'回收站':item.status==='PUBLISHED'?'已发布':'草稿'}</span>{#if item.status==='PUBLISHED'&&item.dirty}<small>有未发布修改</small>{/if}</td><td>{new Date(item.updatedAt).toLocaleDateString('zh-CN')}</td><td><div class="toolbar">{#if trash}<button onclick={()=>action(item,'restore')}>恢复</button>{:else}<button onclick={()=>{selected=item;editing=true;}}>编辑</button>{#if item.status==='PUBLISHED'}<button onclick={()=>action(item,'unpublish')}>下架</button>{/if}<button onclick={()=>action(item,'delete')}>移入回收站</button>{/if}</div></td></tr>{/each}</tbody></table></div>{/if}
<div class="pagination"><button disabled={page<=1} onclick={()=>{page--;void load();}}>上一页</button><span>{page} / {Math.max(1,totalPages)}</span><button disabled={page>=totalPages} onclick={()=>{page++;void load();}}>下一页</button></div></section>{/if}
